    assert.strictEqual(ms('1 week'), 604800000);
  });

  it('still parses the plural form "weeks"', function () {
    assert.strictEqual(ms('2 weeks'), 1209600000);
  });
});
"}, "note": "Changing `weeks?` to `weeks` in the parse regex removes matching for the singular 'week', so ms('1 week') now returns undefined instead of 604800000. The switch still contains a 'week' case, but the regex never lets it be reached."}
```

